<template>
<section aria-label="完整库存候选与共同约束编辑">
 <p>本次原件全集 {{modelValue.member_reviews.length}} 件。日期与全部候选保持完整，分页只改变显示。原量未知、专业签署未知和计量冲突不会被技术审核改成已知。</p>
 <label>本场景明确受审单位<select aria-label="本场景明确受审单位" :value="modelValue.unit_definition_id||''" @change="unit($event.target.value)"><option value="" disabled>明确选择原单位</option><option v-for="s in units" :key="s.source_record_id" :value="s.source_record_id">{{s.payload.original_unit_text}} · {{s.source_record_id}}</option></select></label>
 <label>完整库存观察原件<select aria-label="完整库存观察原件" :value="modelValue.observation?.source_record_id||''" @change="original('observation',$event.target.value)"><option value="" disabled>选择一整件，不自动选最新实盘</option><option v-for="s in observations" :key="s.source_record_id" :value="s.source_record_id">{{s.payload.method}} · {{s.payload.observed_at||'无独立观察时刻'}} · {{s.source_record_id}}</option></select></label>
 <label>完整未来出库情景原件<select aria-label="完整未来出库情景原件" :value="modelValue.future_quantity_scenario?.source_record_id||''" @change="original('future_quantity_scenario',$event.target.value)"><option value="" disabled>选择同一日期域的一整件</option><option v-for="s in futures" :key="s.source_record_id" :value="s.source_record_id">{{s.payload.date_from}} 至 {{s.payload.date_to}} · {{s.source_record_id}}</option></select></label>
 <fieldset><legend>完整有限采购候选集合</legend><p>同一SKU、范围和日期域的全部当前已发布候选 {{candidates.length}} 件必须共同参与。另一单位、未知专业状态或不利费用不能通过筛选排除。零订单基线也必须有真实原件。</p><ul><li v-for="s in candidates" :key="s.source_record_id">{{s.source_record_id}}；{{s.payload===null?'当前正文不可使用':s.payload.orders.length+' 个完整订单'}}；原单位 {{s.unit_definition_id||'未知'}}；专业 {{s.professional_status}}</li></ul><label><input type="checkbox" aria-label="明确纳入本次全部已发布完整候选" :checked="candidateSelected" @change="includeCandidates($event.target.checked)">明确纳入本次全部已发布完整候选</label></fieldset>
 <label>本次共用审阅依据（仅复制文字，不替代逐件用途）<textarea aria-label="本次库存场景共用审阅依据" v-model="sharedBasis" rows="3"/></label><button type="button" :disabled="!inventoryScenarioBasis(sharedBasis)" @click="copyBasis">将本次依据复制到尚未填写的声明</button>
 <fieldset><legend>全体原件逐件用途</legend><table><thead><tr><th>原件定位与状态</th><th>明确用途</th><th>用途依据</th></tr></thead><tbody><tr v-for="r in memberPage" :key="r.source_kind+':'+r.source_record_id"><td>{{r.source_kind}} · {{r.source_record_id}}<br>{{source(r)?.status}}；{{source(r)?.payload===null?'正文已隐去':'完整原件'}}；专业 {{source(r)?.professional_status}}</td><td><select :aria-label="r.source_record_id+' 原件用途'" v-model="r.use"><option value="" disabled>明确用途</option><option value="confirmed" :disabled="source(r)?.status!=='published'||source(r)?.payload===null">明确用于本次审阅</option><option value="excluded">明确其他用途或排除</option><option value="unknown">用途未知</option></select></td><td><textarea :aria-label="r.source_record_id+' 用途依据'" v-model="r.basis_note" rows="2"/></td></tr></tbody></table><nav aria-label="完整库存成员分页"><button type="button" :disabled="memberIndex===0" @click="memberIndex--">上一页原件</button><span>第 {{memberIndex+1}} / {{Math.max(1,Math.ceil(modelValue.member_reviews.length/20))}} 页</span><button type="button" :disabled="(memberIndex+1)*20>=modelValue.member_reviews.length" @click="memberIndex++">下一页原件</button></nav></fieldset>
 <fieldset><legend>全部候选共享逐日约束</legend><p>每日先到期、再收货、按明确FEFO规则出库，最后检查约束。未知不作为零或无限上限。</p><div v-for="d in dayPage" :key="d.date"><h4>{{d.date}}</h4><InventoryConstraintField v-model="d.minimum_end_usable" :label="d.date+'日末可用量下限'"/><InventoryConstraintField v-model="d.maximum_end_total" :label="d.date+'日末总量上限'"/></div><nav aria-label="完整库存日期分页"><button type="button" :disabled="dayIndex===0" @click="dayIndex--">上一页日期</button><span>第 {{dayIndex+1}} / {{Math.ceil(modelValue.daily_constraints.length/7)}} 页</span><button type="button" :disabled="(dayIndex+1)*7>=modelValue.daily_constraints.length" @click="dayIndex++">下一页日期</button></nav></fieldset>
 <InventoryConstraintField v-model="modelValue.shared_budget" label="全部候选共同预算" kind="cost"/>
 <fieldset><legend>明确统一费用口径</legend><label>本场景原币种<input aria-label="本场景原币种" v-model="modelValue.cost_unit.currency_text"></label><label>本场景原费用单位<input aria-label="本场景原费用单位" v-model="modelValue.cost_unit.original_cost_unit_text"></label><label>费用口径核实<select aria-label="费用口径核实" v-model="modelValue.cost_unit.review"><option value="" disabled>明确核实状态</option><option v-for="r in reviews" :key="r" :value="r">{{reviewLabels[r]}}</option></select></label><textarea aria-label="费用口径依据" v-model="modelValue.cost_unit.basis_note" rows="2"/></fieldset>
 <fieldset><legend>政策和延续假设逐项声明</legend><label>共同政策核实<select aria-label="共同政策核实" v-model="modelValue.policy_review"><option value="" disabled>明确政策状态</option><option v-for="r in reviews" :key="r" :value="r">{{reviewLabels[r]}}</option></select></label><textarea aria-label="共同政策依据" v-model="modelValue.policy_basis_note" rows="2"/><label v-for="[key,label] in assumptionLabels" :key="key">{{label}}<select :aria-label="label" v-model="modelValue.assumptions[key]"><option value="" disabled>明确确认或未知</option><option v-for="r in reviews" :key="r" :value="r">{{reviewLabels[r]}}</option></select></label><textarea aria-label="库存延续假设依据" v-model="modelValue.assumptions.basis_note" rows="2"/><label>完整候选集合核实<select aria-label="完整候选集合核实" v-model="modelValue.candidate_set_review"><option value="" disabled>明确完整集合状态</option><option v-for="r in reviews" :key="r" :value="r">{{reviewLabels[r]}}</option></select></label><textarea aria-label="完整候选集合依据" v-model="modelValue.candidate_set_basis_note" rows="2"/></fieldset>
</section>
</template>
<script setup>
import {computed,ref,watch} from 'vue';
import {inventoryScenarioBasis} from '@/api/ai/inventoryScenarios';
import {supportCanonical} from '@/api/inpatientSupport';
import InventoryConstraintField from './InventoryConstraintField.vue';
const props=defineProps({modelValue:{type:Object,required:true},preview:{type:Object,required:true}}),sharedBasis=ref(''),memberIndex=ref(0),dayIndex=ref(0),reviews=['confirmed','not_confirmed','unknown'],reviewLabels={confirmed:'明确确认',not_confirmed:'明确不确认',unknown:'未知'},assumptionLabels=[['opening_carry_forward','原观察结存延续至未来首日'],['no_other_inventory_changes','无其他未表达的库存变化'],['frozen_quantities_unchanged','冻结数量保持不变']];
const all=computed(()=>[...props.preview.unit_definitions,...props.preview.source_records].map(r=>r.source)),sources=computed(()=>props.preview.source_records.map(r=>r.source)),records=computed(()=>new Map(all.value.map(s=>[s.source_kind+':'+s.source_record_id,s]))),units=computed(()=>all.value.filter(s=>s.source_kind==='unit_definition'&&s.status==='published'&&s.eligible&&s.professional_status==='confirmed'&&s.payload!==null)),observations=computed(()=>sources.value.filter(s=>s.source_kind==='inventory_observation'&&s.status==='published'&&s.payload!==null)),samePeriod=s=>['timezone','date_from','date_to'].every(k=>s[k]===props.preview.request[k]),futures=computed(()=>sources.value.filter(s=>s.source_kind==='future_quantity_scenario'&&s.status==='published'&&s.payload!==null&&samePeriod(s))),candidates=computed(()=>sources.value.filter(s=>s.source_kind==='purchase_candidate_plan'&&s.status==='published'&&samePeriod(s)).sort((a,b)=>(a.payload?.orders.length===0?0:1)-(b.payload?.orders.length===0?0:1)||a.source_record_id.localeCompare(b.source_record_id))),candidateSelected=computed(()=>supportCanonical(props.modelValue.candidates.map(r=>r.source_record_id).sort())===supportCanonical(candidates.value.map(s=>s.source_record_id).sort())&&candidates.value.length>0),memberPage=computed(()=>props.modelValue.member_reviews.slice(memberIndex.value*20,(memberIndex.value+1)*20)),dayPage=computed(()=>props.modelValue.daily_constraints.slice(dayIndex.value*7,(dayIndex.value+1)*7));
const refOf=s=>({source_record_id:s.source_record_id,expected_content_hash:s.content_hash,expected_governance_hash:s.governance_hash});
function source(r){return records.value.get(r.source_kind+':'+r.source_record_id);}function unit(id){const s=units.value.find(s=>s.source_record_id===id);if(s)Object.assign(props.modelValue,{unit_definition_id:id,expected_unit_content_hash:s.content_hash,expected_unit_governance_hash:s.governance_hash});}function original(key,id){const s=sources.value.find(s=>s.source_record_id===id);if(s)props.modelValue[key]=refOf(s);}function includeCandidates(value){props.modelValue.candidates=value?candidates.value.map(refOf):[];}
function copyBasis(){if(!inventoryScenarioBasis(sharedBasis.value))return;for(const r of [...props.modelValue.member_reviews,props.modelValue.cost_unit,props.modelValue.assumptions])if(!r.basis_note)r.basis_note=sharedBasis.value;if(!props.modelValue.policy_basis_note)props.modelValue.policy_basis_note=sharedBasis.value;if(!props.modelValue.candidate_set_basis_note)props.modelValue.candidate_set_basis_note=sharedBasis.value;}
watch(()=>props.preview.collection_digest,()=>{memberIndex.value=0;dayIndex.value=0;sharedBasis.value='';});
</script>
<style scoped>section{line-height:1.7}fieldset{margin:16px 0;border:1px solid #ddd;padding:12px}label{display:block;margin:8px 0}input:not([type=checkbox]),select,textarea{display:block;box-sizing:border-box;width:100%;padding:7px;border:1px solid #bbb;background:#fff;color:#222}table{width:100%;border-collapse:collapse;table-layout:fixed}td,th{border:1px solid #ddd;padding:8px;text-align:left;vertical-align:top;overflow-wrap:anywhere}nav{display:flex;gap:14px;margin-top:12px}button{padding:7px 12px}li{overflow-wrap:anywhere}</style>
